export interface AISummaryLabels {
	title: string;
	notice: string;
}

const translations: Record<string, AISummaryLabels> = {
	en: {
		title: "AI summary",
		notice:
			"Generated by AI. Please refer to the original article for accuracy.",
	},
	zh_cn: { title: "AI 总结", notice: "由 AI 生成，仅供参考，请以原文为准。" },
	zh_tw: { title: "AI 摘要", notice: "由 AI 產生，僅供參考，請以原文為準。" },
	ja: {
		title: "AI 要約",
		notice: "AI による要約です。正確な情報は原文をご確認ください。",
	},
	ko: {
		title: "AI 요약",
		notice: "AI가 생성한 요약입니다. 정확한 내용은 원문을 확인하세요.",
	},
	es: {
		title: "Resumen de IA",
		notice:
			"Generado por IA. Consulta el artículo original para verificar la información.",
	},
	th: {
		title: "สรุปโดย AI",
		notice: "สร้างโดย AI โปรดตรวจสอบความถูกต้องจากบทความต้นฉบับ",
	},
	vi: {
		title: "Tóm tắt AI",
		notice:
			"Do AI tạo. Vui lòng tham khảo bài viết gốc để kiểm tra độ chính xác.",
	},
	tr: {
		title: "AI özeti",
		notice:
			"Yapay zekâ tarafından oluşturuldu. Doğruluk için özgün makaleye başvurun.",
	},
	id: {
		title: "Ringkasan AI",
		notice: "Dibuat oleh AI. Silakan merujuk ke artikel asli untuk keakuratan.",
	},
};

export function getAISummaryLabels(language: string): AISummaryLabels {
	const normalized = language.toLowerCase().replaceAll("-", "_");
	return (
		translations[normalized] ??
		translations[normalized.split("_")[0]] ??
		translations.en
	);
}
